import json
flow = json.load(open('DriveToSlackTest.flow'))
for d in flow.get('definitions', []):
    nt = d.get('nodeType', '')
    if 'download' in nt or 'send-file' in nt:
        print('nodeType:', nt)
        ctx = d.get('model', {}).get('context', [])
        for c in ctx:
            print(' ctx:', c.get('name'), '=', c.get('value'))
        idef = d.get('inputDefinition', {})
        print('  inputDef fields:')
        for f in idef.get('fields', []):
            print('   -', f.get('name'), 'required=', f.get('required'), f.get('description','')[:60])
            ref = f.get('reference')
            if ref: print('      ref:', ref)
        form_secs = d.get('form', {}).get('sections', [])
        for sec in form_secs:
            for fld in sec.get('fields', []):
                cp = fld.get('componentProps', {})
                cd = cp.get('connectorDetail', {})
                if cd:
                    print('  connectorDetail:', str(cd)[:200])
" 2>&1

